+// RF-006: largo mínimo del motivo de anulación (regla de auditoría de EMBA).
+export const MOTIVO_MIN_CARACTERES = 10;
+
+// RF-005, RF-006: anula una factura emitida. Devuelve una factura nueva congelada; la original no cambia (ADR-002).
+export function anularFactura(factura, motivo) {
+  if (factura?.estado !== "emitida") throw new Error("Solo se anula una factura emitida");
+  const motivoLimpio = typeof motivo === "string" ? motivo.trim() : "";
+  if ([...motivoLimpio].length < MOTIVO_MIN_CARACTERES)
+    throw new Error(`El motivo de anulación necesita al menos ${MOTIVO_MIN_CARACTERES} caracteres`);
+  // Las líneas se congelan de nuevo: no se confía en que la original venga con ellas congeladas (ADR-002).
+  const items = Object.freeze(factura.items.map((item) => Object.freeze({ ...item })));
+  return Object.freeze({ ...factura, items, estado: "anulada", motivo: motivoLimpio });
+}
