 test("RF-001: NIT numérico de 5 a 12 dígitos", () => {
   assert.ok(validarNit("1023456"));
@@ -30,8 +30,80 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const emitidaEjemplo = () =>
+  emitirFactura({ numero: "001-2026-000123", nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 2, precioUnitarioCentavos: 5000 }] });
+const MOTIVO = "Error en el NIT del cliente";
+
+test("RF-005-a: anular una emitida con motivo devuelve una factura anulada", () => {
+  const a = anularFactura(emitidaEjemplo(), MOTIVO);
+  assert.equal(a.estado, "anulada");
+  assert.equal(a.motivo, MOTIVO);
+});
+
+test("RF-005-b: la original no cambia", () => {
+  const f = emitidaEjemplo();
+  anularFactura(f, MOTIVO);
+  assert.equal(f.estado, "emitida");
+  assert.ok(!("motivo" in f));
+  assert.ok(Object.isFrozen(f));
+});
+
+test("RF-005-c: la anulada también es inmutable (ADR-002)", () => {
+  const a = anularFactura(emitidaEjemplo(), MOTIVO);
+  assert.ok(Object.isFrozen(a));
+  assert.ok(Object.isFrozen(a.items));
+  assert.ok(Object.isFrozen(a.items[0]));
+});
+
+test("RF-005-d: sin motivo se rechaza", () => {
+  for (const m of [undefined, null, "", "   ", 12345678901]) {
+    assert.throws(() => anularFactura(emitidaEjemplo(), m));
+  }
+});
+
+test("RF-005-e: una factura ya anulada no se anula otra vez", () => {
+  const a = anularFactura(emitidaEjemplo(), MOTIVO);
+  assert.throws(() => anularFactura(a, MOTIVO));
+});
+
+test("RF-005-f: la anulada conserva los datos y montos de la original", () => {
+  const f = emitidaEjemplo();
+  const a = anularFactura(f, MOTIVO);
+  for (const k of ["numero", "nit", "razonSocial", "totalCentavos", "ivaCentavos", "netoCentavos"]) {
+    assert.equal(a[k], f[k]);
+  }
+  assert.deepEqual(a.items, f.items);
+});
+
+test("RF-006-a: el motivo tiene al menos 10 caracteres", () => {
+  assert.throws(() => anularFactura(emitidaEjemplo(), "123456789"));
+  assert.equal(anularFactura(emitidaEjemplo(), "1234567890").motivo, "1234567890");
+});
+
+test("RF-006-b: los espacios de los bordes no cuentan y no se guardan", () => {
+  assert.throws(() => anularFactura(emitidaEjemplo(), "  corto   "));
+  assert.equal(anularFactura(emitidaEjemplo(), "  1234567890  ").motivo, "1234567890");
+});
+
 test("formato de montos para personas", () => {
   assert.equal(formatearBs(123450), "1.234,50 Bs");
   assert.equal(formatearBs(5), "0,05 Bs");
   assert.equal(formatearBs(-100000000), "-1.000.000,00 Bs");
 });
+
+test("RF-005-c (revisión): la anulada congela las líneas aunque la emitida venga armada a mano sin congelar", () => {
+  const armada = { numero: "001-2026-000124", nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 1, precioUnitarioCentavos: 1000 }], totalCentavos: 1000, ivaCentavos: 130, netoCentavos: 870, estado: "emitida" };
+  const a = anularFactura(armada, MOTIVO);
+  assert.ok(Object.isFrozen(a));
+  assert.ok(Object.isFrozen(a.items));
+  assert.ok(Object.isFrozen(a.items[0]));
+  assert.throws(() => { "use strict"; a.items[0].cantidad = 99; }, TypeError);
+  assert.equal(armada.estado, "emitida"); // la original no se toca
+  assert.ok(!Object.isFrozen(armada.items[0]));
+  assert.equal(armada.items[0].cantidad, 1);
+});
+
+test("RF-006-c: el largo del motivo se cuenta en caracteres visibles, un emoji cuenta como uno", () => {
+  assert.throws(() => anularFactura(emitidaEjemplo(), "😀".repeat(9)));
+  assert.equal(anularFactura(emitidaEjemplo(), "😀".repeat(10)).motivo, "😀".repeat(10));
+});
